import functools
import inspect
from typing import ForwardRef, Any, Dict
from fastapi.dependencies.utils import get_typed_signature

class B:
    pass

def original_func(x: "B"):
    return x

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

wrapped_func = wrapper(original_func)

# The original_func has B in its globals.
# The wrapped_func has its own globals.
# If we call get_typed_signature(wrapped_func), it should use original_func's globals.

try:
    sig = get_typed_signature(wrapped_func)
    print("Success!")
    print(sig)
except Exception as e:
    print(f"Failed: {e}")
    import traceback
    traceback.print_exc()

